const b=$input.first().json.body;
if(!b||typeof b!=='object'||Array.isArray(b)) throw new Error('JSON object required');
if(JSON.stringify(b).length>14000) throw new Error('Request too large');
const bounded=(v,max,label,required=false)=>{if(v===undefined||v===null)v='';if(typeof v!=='string'||v.length>max||(required&&!v.trim()))throw new Error('Invalid '+label);return v.trim();};
const request_id=bounded(b.request_id,100,'request_id',true);
const sessionId=bounded(b.session_id,160,'session_id',true);
if(!/^[A-Za-z0-9_-]{16,100}$/.test(request_id)||!/^[A-Za-z0-9_:-]{1,160}$/.test(sessionId))throw new Error('Invalid identifiers');
const request=bounded(b.request,2000,'request',true);
const context=bounded(b.context,6000,'context');
const lead={};const limits={name:150,industry:150,email:254,phone:40,company:200,role:150,need:1500,timeline:300,budget_readiness:300,authority:300};
if(b.lead!==undefined&&(!b.lead||typeof b.lead!=='object'||Array.isArray(b.lead)))throw new Error('Invalid lead');
for(const [k,max] of Object.entries(limits))lead[k]=bounded(b.lead?.[k],max,k);
const confirmed=b.follow_up_confirmed===true;
if (b.business_id !== undefined && b.business_id !== 'jayeola') throw new Error('Wrong business');
if(confirmed && (b.consent_evidence!=='provider_challenge_v1' || !/^lead_[a-f0-9]{32}$/.test(b.Lead_ID || '') || b.Lead_ID!=='lead_'+request_id)) throw new Error('Confirmation required');
if(confirmed && (!lead.name || !lead.need || !(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email) || /^\+[1-9][0-9]{7,14}$/.test(lead.phone)))) throw new Error('Missing lead fields');
if(!confirmed) for(const k of Object.keys(lead)) lead[k]='';

// Fixed server scope. Never route tenants, sheets or recipients using model input.
const company_id='jayeola';
const packet={request,context,lead,follow_up_confirmed:confirmed,request_id};
const normalized=[{json:{request_id,sessionId,company_id,lead,Lead_ID:b.Lead_ID || null,memory_key:`${company_id}:voice:${sessionId}`,metadata_filter:{company_id},follow_up_confirmed:confirmed,chatInput:JSON.stringify(packet)}}];
const q=normalized[0].json;
q.consent_evidence=confirmed?b.consent_evidence:'';
q.gateway_payload_hash=$input.first().json.headers?.['x-voice-payload-hash'] || '';
if(confirmed && !/^[a-f0-9]{64}$/.test(q.gateway_payload_hash)) throw new Error('Gateway payload fingerprint required');
q.chatInput=JSON.stringify({request,context,lead:q.lead,request_id,Lead_ID:q.Lead_ID,company_id,follow_up_confirmed:confirmed});
return normalized;

const q = $('Normalize Voice Request').first().json;
const raw = $input.first().json;
const aliases = {create_lead1:'create_lead1',create_lead:'create_lead1',notify_jaye1:'notify_jaye1',notify_jaye:'notify_jaye1'};
const allowed = new Set(['Get_Info','Get Info','Knowledge_Base_Q_A_Tool','Knowledge Base Q&A Tool','Think',...Object.keys(aliases)]);
const decode = value => { try { return typeof value === 'string' ? JSON.parse(value) : value; } catch { return null; } };
const used = [];
let lead = false, notification = false, attempted = false;
for (const step of Array.isArray(raw.intermediateSteps) ? raw.intermediateSteps : []) {
  const tool = step.action?.tool;
  if (!allowed.has(tool)) continue;
  if (!used.includes(tool)) used.push(tool);
  if (!aliases[tool]) continue;
  attempted = true;
  if (lead !== true) lead = null;
  if (aliases[tool] === 'notify_jaye1' && notification !== true) notification = null;
  const observation = decode(step.observation);
  const rows = Array.isArray(observation) ? observation : [observation];
  for (let receipt of rows) {
    receipt = decode(receipt?.json ?? receipt);
    if (!receipt || receipt.request_id !== q.request_id || receipt.Lead_ID !== q.Lead_ID || !['completed','partial'].includes(receipt.status)) continue;
    if (aliases[tool] === 'create_lead1' && receipt.actions?.lead_saved === true && receipt.evidence?.lead_id === q.Lead_ID) lead = true;
    if (aliases[tool] === 'notify_jaye1' && receipt.actions?.lead_saved === true && receipt.evidence?.lead_id === q.Lead_ID) lead = true;
    if (aliases[tool] === 'notify_jaye1' && receipt.actions?.lead_saved === true && receipt.actions?.notification_sent === true &&
        Number.isInteger(receipt.evidence?.message_id) && receipt.evidence.message_id > 0) { lead = true; notification = true; }
  }
}
let status, reply;
if (lead === true && notification === true) {
  status = 'completed'; reply = 'Your details were saved and the team was notified.';
} else if (lead === true) {
  status = 'partial'; reply = 'Your details were saved, but I could not confirm the notification.';
} else if (attempted || raw.error) {
  status = 'unknown'; reply = 'I could not confirm the outcome. Please do not submit the same follow-up again yet.';
} else if (q.follow_up_confirmed) {
  status = 'needs_information'; reply = 'I could not complete that follow-up. Please ask the team to review this request.';
} else {
  const parsed = decode(raw.output);
  const valid = parsed && ['answered','needs_information'].includes(parsed.status) && typeof parsed.reply === 'string' && parsed.reply.trim();
  status = valid ? parsed.status : 'needs_information';
  reply = valid ? parsed.reply.trim().slice(0,1200) : 'Please clarify your question, or confirm the details you want shared for a follow-up.';
}
return [{json:{request_id:q.request_id, ...(q.follow_up_confirmed ? {Lead_ID:q.Lead_ID} : {}), status, reply,
  actions:{lead_saved:lead,notification_sent:notification},tools_used:used}}];
